from lib import *
S = SS('j258')
steps = [
    step("同一段 sun.misc.Unsafe 代码(allocateMemory / putLong / getLong / freeMemory)在 JDK 17 与 21 上输出 getLong = 42,没有任何警告;在 JDK 27 上也成功,但会打印 WARNING: A terminally deprecated method in sun.misc.Unsafe has been called(sun.misc.Unsafe::allocateMemory will be removed in a future release)。JDK 27 的 --sun-misc-unsafe-memory-access 选项:allow 不警告;warn 打印警告;debug 逐个方法打印并带栈(allocateMemory、putLong……);deny 让 allocateMemory 抛 UnsupportedOperationException。", t=tl(S(1)), done=lidx(S(1), '[JDK 17]', '[JDK 21]', '[JDK 27]'), mark=lidx(S(1), 'memory-access=allow', 'memory-access=warn', 'memory-access=debug', 'memory-access=deny'), kv=KV([['JDK 17 / 21', '成功,无警告'], ['JDK 27 默认', '成功,打印 terminally deprecated 警告'], ['deny', 'allocateMemory 抛 UnsupportedOperationException']], ['deny'])),
    step("Unsafe.objectFieldOffset 的限制:普通类的字段可以取偏移(JDK 17、21 是 12,JDK 27 是 16——对象头大小不同);record 的字段在 JDK 17、21、27 上都抛 UnsupportedOperationException: can't get field offset on a record class;lambda 的隐藏类(捕获字段 arg$1)也抛 UnsupportedOperationException: can't get field offset on a hidden class。VarHandle 是替代:能读 record 字段(x = 7),但写 final 字段抛 UnsupportedOperationException;对普通 volatile 字段 compareAndSet(0, 5) = true。", t=tl(S(2)), done=lidx(S(2), '[JDK 17]', '普通类的字段'), mark=lidx(S(2), 'record 的字段', 'lambda(隐藏类)', 'VarHandle 读 record 字段', 'VarHandle 对普通 volatile 字段'), kv=KV([['objectFieldOffset', '普通类可以(12 / 16),record 与隐藏类抛 UnsupportedOperationException'], ['VarHandle', '读 record 字段可以,写 final 抛异常;CAS 普通 volatile 字段可以']], ['VarHandle'])),
    step("堆内外读写的成本(JDK 27,7 轮中位数,写 + 读各 1,048,576 个 long):long[] 0.48 ns/元素、Unsafe 堆外 0.51、MemorySegment.get(JAVA_LONG) 0.48、MemorySegment 的 VarHandle 0.47、DirectByteBuffer 0.49、LongBuffer 0.49、byte[] + byteArrayViewVarHandle 0.50——全部在同一量级。这是我第二次测:第一版把七种访问方式放在同一个带 switch 的大方法里,VarHandle 的两种测到 9.4 与 6.6 ns、ByteBuffer 约 4 ns;把每种访问方式拆成各自的小方法之后,全部变成约 0.5 ns。微基准里方法的组织方式本身就会改变结论。", t=tl(S(3)), done=lidx(S(3), 'long[](堆内数组)', 'Unsafe(堆外地址)'), mark=lidx(S(3), 'MemorySegment.get(JAVA_LONG, offset)', 'MemorySegment 的 VarHandle', 'DirectByteBuffer.getLong', 'byte[] + byteArrayViewVarHandle'), b=bars([['long[]', 0.48, '0.48 ns'], ['Unsafe', 0.51, '0.51 ns'], ['MemorySegment.get', 0.48, '0.48 ns'], ['MemorySegment VarHandle', 0.47, '0.47 ns'], ['DirectByteBuffer', 0.49, '0.49 ns'], ['byte[] VarHandle', 0.5, '0.50 ns']], 0.6, done=[0, 1, 2, 3, 4, 5]), kv=KV([['七种访问方式', '全部约 0.47–0.51 ns / 元素'], ['第一版(同一个大方法里)', 'VarHandle 6.6–9.4 ns,ByteBuffer 约 4 ns']], ['第一版(同一个大方法里)'])),
    step("计数器的几种写法(JDK 27,2,000 万次自增,每次 = 总耗时 ÷ 总次数,5 轮中位数)。1 个线程:AtomicLong.incrementAndGet 1.9 ns,VarHandle.getAndAdd 4.0,VarHandle.compareAndSet 循环 8.3,Unsafe.compareAndSwapLong 循环 8.2,synchronized + long++ 5.6,LongAdder 5.0;4 个线程:AtomicLong 17.0,VarHandle.getAndAdd 43.5,VarHandle CAS 循环 113.4,Unsafe CAS 循环 92.8,synchronized 20.5,LongAdder 1.3。VarHandle 与 Unsafe 的 CAS 循环成本相同(8.3 vs 8.2 ns),没有“Unsafe 更快”;竞争下 CAS 循环最差,LongAdder 最好。", t=tl(S(4)), done=lidx(S(4), '1 线程 AtomicLong', '1 线程 VarHandle.getAndAdd', '1 线程 VarHandle.compareAndSet'), mark=lidx(S(4), '1 线程 Unsafe.compareAndSwapLong', '4 线程 VarHandle.compareAndSet', '4 线程 Unsafe.compareAndSwapLong', '4 线程 LongAdder'), b=bars([['1 线程 VarHandle CAS', 8.3, '8.3 ns'], ['1 线程 Unsafe CAS', 8.2, '8.2 ns'], ['4 线程 VarHandle CAS', 113.4, '113.4 ns'], ['4 线程 Unsafe CAS', 92.8, '92.8 ns'], ['4 线程 LongAdder', 1.3, '1.3 ns']], 115, done=[0, 1, 2, 3, 4]), kv=KV([['1 线程 CAS 循环', 'VarHandle 8.3 ns / Unsafe 8.2 ns'], ['4 线程', 'CAS 循环 93–113 ns,AtomicLong 17.0,LongAdder 1.3']], ['4 线程'])),
    step("堆外内存的生命周期(JDK 27,100 块 4 MiB 并写满):Unsafe.allocateMemory 不 freeMemory:RSS 42 MiB → 453 MiB,System.gc() 之后仍是 455 MiB(增加 412 MiB)——GC 管不到它;Arena.ofConfined 每块用完 close:RSS 峰值 61 MiB、结束 63 MiB(增加 20 MiB);Arena.ofAuto 不 close:RSS 63 → 461 MiB,gc 之后 317 MiB(增加 253 MiB,交给 GC,回收不即时也不保证归还给系统)。而且 MemorySegment 有检查:访问已 close 的 Arena 的段抛 IllegalStateException: Already closed;越界读抛 IndexOutOfBoundsException。Unsafe 释放后再访问不会有任何检查。", t=tl(S(5)), done=lidx(S(5), 'Unsafe.allocateMemory 100', 'Arena.ofConfined'), mark=lidx(S(5), 'Arena.ofAuto', '访问已 close', '越界读 MemorySegment'), b=bars([['Unsafe 不 free:RSS 增加', 412, '412 MiB'], ['Arena.ofAuto + gc:增加', 253, '253 MiB'], ['Arena.ofConfined:增加', 20, '20 MiB']], 412, done=[0, 1, 2]), kv=KV([['Unsafe 不 freeMemory', 'gc 后 RSS 仍多 412 MiB'], ['Arena.ofConfined', 'close 后只多 20 MiB;越界与已关闭都会抛异常'], ['Arena.ofAuto', 'gc 后多 253 MiB']], ['Arena.ofConfined'])),
]
A = mkartj('j258', 258, 'Java,Unsafe,VarHandle,MemorySegment,Foreign Memory,堆外内存,真实验证,动画演示',
    '在 JDK 17 / 21 / 27 上实测 sun.misc.Unsafe 与替代方案:JDK 27 默认打印 terminally deprecated 警告,deny 时抛异常;objectFieldOffset 对 record 与隐藏类抛 UnsupportedOperationException;MemorySegment / VarHandle / ByteBuffer 与 Unsafe 的读写都约 0.5 ns;VarHandle 与 Unsafe 的 CAS 成本相同;Unsafe 不 free 的 412 MiB 在 gc 后仍在,Arena 有边界与生命周期检查。',
    'sun.misc.Unsafe 正在被淘汰。这篇用真实运行回答:Unsafe 在新 JDK 上到底会发生什么,哪些东西它做不到,以及 VarHandle 与 MemorySegment / Arena 这些替代方案在性能和安全性上是否能顶上。',
    [('WARNING', 'JDK 27 默认调用 Unsafe.allocateMemory 时的行为(JDK 17 / 21 无警告;--sun-misc-unsafe-memory-access=deny 抛 UnsupportedOperationException)'), ('0.47–0.51 ns', 'long[]、Unsafe、MemorySegment、DirectByteBuffer、VarHandle 读写 100 多万个 long 的每元素成本'), ('412 vs 20 MiB', 'Unsafe 不 freeMemory 与 Arena.ofConfined 在 100 块 4 MiB 后的 RSS 增量')],
    [('JDK 17 / 21 / 27 上的 Unsafe', None), ('objectFieldOffset 的限制', None), ('读写成本', None), ('CAS', None), ('堆外内存的生命周期', None)],
    steps, [ENV_J + '。JDK 17.0.20、21.0.12(只测 Unsafe 与 VarHandle)、27(MemorySegment / Arena 是正式 API);MemorySegment 测试用 JDK 27 的 java.lang.foreign;计数器用 System.nanoTime 的 5 轮中位数,不是 JMH', '没有验证:Unsafe 的 park / unpark / defineClass / allocateInstance 等其它方法、JDK 22 / 23 / 24 / 25 / 26 的中间行为(JEP 498 的逐版本变化)、JMH 下的结论、Unsafe 在 Netty / Kryo / Hazelcast 等库里的使用与迁移情况、JNI / Linker API(java.lang.foreign.Linker)'], 'Unsafe 的替代方案')
